'use strict';

var resolve = require( 'path' ).resolve;
var tape = require( 'tape' );
var tryRequire = require( '@stdlib/utils/try-require' );
var Float64Array = require( '@stdlib/array/float64' );
var Int32Array = require( '@stdlib/array/int32' );
var SharedArrayBuffer = require( '@stdlib/array/shared-buffer' );
var getGlobal = require( '@stdlib/utils/global' );
var common = require( './common.js' );
var eligibility = require( './../lib/can_use_native.js' );
var factory = require( './../lib/factory.js' );
var base = require( './../lib/base.js' );
var addon = tryRequire(resolve(__dirname, './../src/addon.node'));
var native = tryRequire(resolve(__dirname, './../lib/native.js'));
var opts = {
	'skip': native instanceof Error
};

tape('main export is a function', opts, function test(t) {
	t.ok( true, __filename );
	t.strictEqual(typeof native, 'function');
	t.end();
});

tape( 'raw addon rejects physical overlap across distinct shared identities', {
	'skip': native instanceof Error || SharedArrayBuffer === null
}, function test( t ) {
	var whole;
	var clone;
	var a;
	var e;
	var p;
	whole = new SharedArrayBuffer( 128 );
	clone = getGlobal().structuredClone;
	clone = ( clone ) ? clone( whole ) : whole;
	a = new Float64Array( whole, 0, 4 );
	e = new Float64Array( clone, 16, 2 );
	p = new Int32Array( [ -1, -2 ] );
	a.set( [ 1, 92, 3, 4 ] );
	t.throws( function call() {
		addon( 121, 67, 2, a, 1, 2, 0, e, 1, 0, p, 1, 0 );
	}, RangeError, 'physical indexed envelopes overlap' );
	t.deepEqual( a, new Float64Array( [ 1, 92, 3, 4 ] ), 'no A writes' );
	t.deepEqual( p, new Int32Array( [ -1, -2 ] ), 'no P writes' );
	t.end();
} );

tape('actual compiled native addon matches independent-direction fixtures', opts, function test(t) {
	t.strictEqual(typeof addon, 'function', 'actual node binary export loaded');
	common.corpus(t, native);
	t.end();
});
tape('native eligibility covers complete sums and valid wide singleton fallback', function test(t) {
	var calls;
	var fn;
	var a;
	var e;
	var p;
	calls = 0;
	fn = factory(function dispatch() {
		if (eligibility(arguments)) {
			calls += 1;
			return base.apply(null, arguments);
		}
		return base.apply(null, arguments);
	});
	a = new Float64Array([5]);
	e = new Float64Array([7]);
	p = new Int32Array([1]);
	t.strictEqual(eligibility([
		121,
		67,
		2,
		null,
		2000000000,
		1000000000,
		0,
		null,
		1,
		0,
		null,
		1,
		0
	]), false, 'full corner sum exceeds native width');
	t.strictEqual(eligibility([
		121,
		67,
		2,
		null,
		1,
		2,
		2147483646,
		null,
		1,
		0,
		null,
		1,
		0
	]), false, 'offset plus active corner');
	t.strictEqual(eligibility([
		121,
		67,
		2,
		null,
		1,
		2,
		0,
		null,
		2,
		2147483646,
		null,
		1,
		0
	]), false, 'vector offset plus delta');
	t.strictEqual(fn.ndarray('upper', 'convert', 1, a, 9007199254740991, -9007199254740991, 0, e, 9007199254740991, 0, p, -9007199254740991, 0), 0);
	t.strictEqual(calls, 0, 'wide unused metadata goes to JavaScript');
	t.strictEqual(e[0], 0);
	t.strictEqual(a[0], 5);
	t.end();
});
tape('raw addon rejects malformed and fractional inputs before mutation', opts, function test(t) {
	var slots;
	var args;
	var a;
	var e;
	var i;
	var p;
	var x;
	a = new Float64Array([
		1,
		2,
		3,
		4
	]);
	e = new Float64Array([
		8,
		9
	]);
	p = new Int32Array([
		-1,
		-2
	]);
	args = [
		121,
		67,
		2,
		a,
		1,
		2,
		0,
		e,
		1,
		0,
		p,
		1,
		0
	];
	slots = [
		0,
		1,
		2,
		4,
		5,
		6,
		8,
		9,
		11,
		12
	];
	for (i = 0; i < slots.length; i++) {
		x = args.slice();
		x[slots[i]] += 0.5;
		t.throws(addon.apply.bind(addon, null, x), RangeError, 'fractional scalar ' + slots[i]);
	}
	x = args.slice();
	x[4] = 0;
	x[5] = 0;
	x[8] = 0;
	x[11] = 0;
	x[2] = 2147483647;
	t.throws(function call() {
		addon.apply(null, x);
	}, RangeError, 'tiny broadcast rejected before workspace allocation');
	x = args.slice();
	x[4] = 1;
	x[5] = 1;
	t.throws(function call() {
		addon.apply(null, x);
	}, RangeError, 'full square collisions');
	x = args.slice();
	x[8] = 0;
	t.throws(function call() {
		addon.apply(null, x);
	}, RangeError, 'mutable E broadcast');
	x = args.slice();
	x[10] = new Int32Array([
		-1,
		0
	]);
	t.throws(function call() {
		addon.apply(null, x);
	}, RangeError, 'late malformed pivots');
	t.deepEqual(a, new Float64Array([
		1,
		2,
		3,
		4
	]), 'no A writes');
	t.deepEqual(e, new Float64Array([
		8,
		9
	]), 'no E writes');
	t.deepEqual(p, new Int32Array([
		-1,
		-2
	]), 'no P writes');
	t.strictEqual(addon(121, 67, 0, null, NaN, null, null, null, null, null, null, null, null), 0, 'validated empty raw addon reads no buffers/metadata');
	t.end();
});
tape('native bridge accepts disjoint indexed subviews and ignores exposed metadata getters', opts, function test(t) {
	var overlapping;
	var reads;
	var whole;
	var a;
	var e;
	var p;
	whole = new Float64Array(16);
	a = new Float64Array(whole.buffer, 8, 4);
	e = new Float64Array(whole.buffer, 64, 2);
	p = new Int32Array(whole.buffer, 96, 2);
	reads = 0;
	a.set([
		1,
		92,
		3,
		4
	]);
	e.set([
		8,
		9
	]);
	p.set([
		-1,
		-2
	]);
	Object.defineProperty(a, 'buffer', {
		'get': function get() {
			reads += 1;
			throw new Error('untrusted getter');
		}
	});
	t.strictEqual(native('column-major', 'upper', 'convert', 2, a, 2, e, p), 0);
	t.strictEqual(e[1], 3);
	t.strictEqual(reads, 0, 'captured intrinsic metadata');
	t.strictEqual(native('column-major', 'upper', 'revert', 2, a, 2, e, p), 0);
	t.strictEqual(a[2], 3);
	overlapping = new Float64Array(whole.buffer, 16, 2);
	t.throws(function call() {
		native('column-major', 'upper', 'convert', 2, a, 2, overlapping, p);
	}, RangeError, 'overlapping indexed envelopes');
	t.end();
});
